import {
  createChange,
  createReorder,
  createRovingFocus,
  createSelection,
  definePrimitive,
  idPart,
  type ChangeDetails,
  type ChangeOptions,
  type ReorderDraft,
  type ReorderOrientation,
  type ReorderReason,
} from "@ui-sdk/core"

import { settled } from "@/lib/action-refusal"
import { sortableLabels, type SortableLabels } from "@/components/ui/sortable-labels"
import { isStringArray } from "@/lib/narrow"

type SortableReason = ReorderReason
type SortableSelectReason = "item-press" | "imperative"
type SortableAutoScroll = false | { edge?: number; speed?: number }

type SortableOptions = {
  value?: readonly string[]
  defaultValue?: readonly string[]
  /** Runs once per drop or move, with the whole new order; `details.cancel()` keeps the old one. */
  onValueChange?: (value: string[], details: ChangeDetails<SortableReason>) => void
  orientation?: ReorderOrientation
  /** Items move by their `SortableHandle` only, so the rest of an item, like its buttons, stays clickable. */
  handle?: boolean
  /** Items that move together when one of them is picked up. Ctrl or Cmd and a press toggle one, Shift extends. */
  selected?: readonly string[]
  defaultSelected?: readonly string[]
  onSelectedChange?: (selected: string[], details: ChangeDetails<SortableSelectReason>) => void
  /** Items that can't be picked up; they still make room for others. */
  disabledKeys?: readonly string[]
  /** Drags a copy above the page, so a scrolling list neither clips the item nor grows under it. Read on mount. */
  preview?: boolean
  /** Edge scrolling during a `preview` drag; `false` turns it off. Read on mount. */
  autoScroll?: SortableAutoScroll
  /** An item's name for announcements and agents; its text by default. */
  itemLabel?: (key: string) => string | undefined
  labels?: Partial<SortableLabels>
  /** Whether agents get `move` and `reorder`. A host that offers its own, confirmed action turns these off. */
  agentMoves?: boolean
}

const asList = (value: readonly string[] | undefined) => (value ? [...value] : undefined)

function checkOrder(next: unknown, current: readonly string[]): string[] {
  if (!isStringArray(next)) throw new TypeError("reorder takes the full list of item ids, in their new order.")
  const keys = next
  const missing = current.filter((key) => !keys.includes(key))
  const unknown = keys.filter((key) => !current.includes(key))
  if (missing.length > 0 || unknown.length > 0 || new Set(keys).size !== keys.length) {
    throw new RangeError(`reorder takes each of these ids once: ${current.join(", ")}.`)
  }
  return keys
}

function reasonOf(options: unknown): { reason: SortableReason; event?: Event } {
  if (typeof options !== "object" || options === null) return { reason: "imperative" }
  const { reason = "imperative", event } = options as ChangeOptions<SortableReason>
  return { reason, event: event instanceof Event ? event : undefined }
}

const textOf = (el: HTMLElement | undefined) => el?.textContent?.replaceAll(/\s+/g, " ").trim() || undefined

function shown(options: SortableOptions) {
  return {
    handle: options.handle ?? false,
    orientation: options.orientation ?? ("vertical" as ReorderOrientation),
    agentMoves: options.agentMoves ?? true,
    preview: options.preview ?? false,
    disabledKeys: options.disabledKeys ?? ([] as readonly string[]),
    labels: { ...sortableLabels, ...options.labels },
    itemLabel: options.itemLabel,
  }
}

const sortable = definePrimitive({
  name: "sortable",
  options: {
    value: "list",
    defaultValue: "list",
    onValueChange: "callback",
    orientation: "string",
    handle: "boolean",
    selected: "list",
    defaultSelected: "list",
    onSelectedChange: "callback",
    disabledKeys: "list",
    preview: "boolean",
    autoScroll: "value",
    itemLabel: "value",
    labels: "value",
    agentMoves: "boolean",
  },
  controlled: ["value", "selected"],
  state: (options: SortableOptions) => ({
    value: asList(options.value ?? options.defaultValue) ?? [],
    selected: asList(options.selected ?? options.defaultSelected) ?? [],
    moving: null as ReorderDraft | null,
    focused: null as string | null,
    ...shown(options),
  }),
  sync: (options) => ({
    ...(options.value === undefined ? {} : { value: [...options.value] }),
    ...(options.selected === undefined ? {} : { selected: [...options.selected] }),
    ...shown(options),
  }),
  api: (context) => {
    const change = createChange(context)
    const labels = () => context.store.get().labels
    const disabled = (key: string) => context.store.get().disabledKeys.includes(key)
    const selection = createSelection(context, {
      key: "selected",
      set: (value, details) => change("selected", value, details),
      order: () => context.store.get().value,
      multiple: () => true,
    })
    const roving = createRovingFocus(context, {
      slot: "entry",
      key: "focused",
      orientation: () => (context.store.get().orientation === "horizontal" ? "horizontal" : "vertical"),
    })
    const handles = createRovingFocus(context, {
      slot: "handle",
      key: "focused",
      orientation: () => (context.store.get().orientation === "horizontal" ? "horizontal" : "vertical"),
    })
    const autoScroll = context.options().autoScroll
    const reorder = createReorder(context, {
      slot: "entry",
      key: "value",
      draft: "moving",
      set: (value, details) => change("value", value, details),
      orientation: () => context.store.get().orientation,
      group: (key) => {
        const { selected } = context.store.get()
        return selected.includes(key) ? selected : [key]
      },
      preview: context.options().preview ?? false,
      createAutoScroll: autoScroll === false ? false : { edge: 40, speed: 14, ...autoScroll },
      disabled: ({ key }) => disabled(key),
      label: (key) => context.options().itemLabel?.(key) ?? textOf(itemElement(key)),
      message: (message) => labels().message(message),
    })
    const itemElement = (key: string) => roving.items().find((item) => item.key === key)?.el
    const labelOf = (key: string) => context.options().itemLabel?.(key) ?? textOf(itemElement(key)) ?? key
    const check = (key: unknown) => {
      const { value } = context.store.get()
      if (typeof key !== "string" || !value.includes(key)) {
        throw new RangeError(`No item "${String(key)}". Items: ${value.join(", ")}.`)
      }
      return key
    }

    return {
      drag: reorder,
      roving,
      handles,
      selection,
      labels,
      disabled,
      /** Moves one item to `index` in the order, counting from 0, as a "Move to top" menu item would. */
      move(key: unknown, index: unknown) {
        const id = check(key)
        const { value } = context.store.get()
        if (typeof index !== "number" || !Number.isInteger(index) || index < 0 || index >= value.length) {
          throw new RangeError(`move takes an index from 0 to ${String(value.length - 1)}.`)
        }
        if (disabled(id)) throw new Error(`Item "${id}" can't be moved.`)
        const { selected } = context.store.get()
        const alone = !selected.includes(id) || selected.length === 1
        if (alone && value.indexOf(id) === index) return true
        return settled(reorder.move(id, index), "move")
      },
      /** Replaces the whole order at once. */
      reorder(order: unknown, options?: ChangeOptions<SortableReason>) {
        const { value } = context.store.get()
        const next = checkOrder(order, value)
        const moved = next.filter((key, index) => key !== value[index] && disabled(key))
        if (moved.length > 0) throw new Error(`Items can't be moved: ${moved.join(", ")}.`)
        return settled(change("value", next, reasonOf(options)), "reorder", reasonOf(options))
      },
      press(event: PointerEvent, key: string) {
        const why = { reason: "item-press" as const, event }
        if (event.shiftKey) selection.extend(key, { ...why, from: context.store.get().focused })
        else if (event.metaKey || event.ctrlKey) selection.toggle(key, why)
      },
      keydown(event: KeyboardEvent, key: string, el: HTMLElement, focus: typeof roving) {
        if (event.key === " " && (event.ctrlKey || event.metaKey) && !context.store.get().moving) {
          event.preventDefault()
          selection.toggle(key, { reason: "item-press", event })
          return
        }
        if (!reorder.keydown(event, key)) focus.keydown(event, el)
      },
      items: () => context.store.get().value.map((key) => ({ value: key, label: labelOf(key) })),
    }
  },
  slots: (slot) => ({
    root: slot<object, { order: string[]; moving: boolean }>({
      role: (state) => (state.handle ? "list" : "listbox"),
      roles: ["list", "listbox"],
      keys: { none: "Each item or handle handles its own keys." },
      state: (state, { api }) => ({ order: api.drag.order(state), moving: state.moving !== null }),
      attrs: (state) => ({
        "aria-roledescription": state.labels.list,
        "aria-orientation": state.handle || state.orientation === "grid" ? undefined : state.orientation,
        "aria-multiselectable": state.handle ? undefined : "true",
        "data-orientation": state.orientation,
        "data-preview": state.preview ? "" : undefined,
        "data-handle": state.handle ? "" : undefined,
        "data-moving": state.moving ? "" : undefined,
        "data-dragging": state.moving?.pointer ? "" : undefined,
      }),
    }),
    entry: slot<{ value: string }, { moving: boolean; dragging: boolean; selected: boolean }>({
      props: { value: "string" },
      role: (state) => (state.handle ? "listitem" : "option"),
      roles: ["listitem", "option"],
      focus: (state) => (state.handle ? { none: "Its handle takes focus." } : "roving"),
      press: { none: "Space and Enter pick the item up on keydown; a click does nothing more." },
      keys: (state) =>
        state.handle ? [] : [" ", "Enter", "ArrowUp", "ArrowDown", "ArrowLeft", "ArrowRight", "Home", "End", "Escape"],
      state: (state, { api, key }) => ({
        moving: api.drag.moving(state, key),
        dragging: api.drag.dragging(state, key),
        selected: state.selected.includes(key),
      }),
      attrs: (state, { api, key, id }) => {
        const moving = api.drag.moving(state, key)
        return {
          "aria-roledescription": state.handle ? undefined : state.labels.item,
          "aria-selected": state.handle ? undefined : String(state.selected.includes(key) || moving),
          "aria-describedby": state.handle ? undefined : `${id}-instructions`,
          "aria-disabled": state.disabledKeys.includes(key) ? "true" : undefined,
          tabindex: state.handle ? undefined : api.roving.tabIndex(state, { key, props: { value: key } }),
          "data-sortable-item": idPart(key),
          "data-moving": moving ? "" : undefined,
          "data-grabbed": api.drag.dragging(state, key) ? "" : undefined,
          "data-checked": state.selected.includes(key) ? "" : undefined,
          "data-disabled": state.disabledKeys.includes(key) ? "" : undefined,
        }
      },
      on: {
        keydown: (event, { el, api, key, store }) => {
          if (store.get().handle || !el || event.target !== el) return
          api.keydown(event, key, el, api.roving)
        },
        pointerdown: (event, { api, key, store }) => {
          if (store.get().handle || event.button !== 0) return
          api.press(event, key)
          api.drag.pointerdown(event, key)
        },
      },
      bind: (el, part) => {
        const cleanups = [part.api.roving.bind(el, part), part.api.drag.bind(el, part)]
        return () => cleanups.forEach((cleanup) => cleanup())
      },
    }),
    handle: slot<{ value: string }>({
      props: { value: { kind: "string", from: "entry", required: true } },
      role: "button",
      focus: "roving",
      press: { none: "Space and Enter pick the item up on keydown; a press alone does nothing." },
      attrs: (state, { api, key, id }) => {
        const moving = api.drag.moving(state, key)
        return {
          type: "button",
          "aria-label": state.labels.handle(state.itemLabel?.(key) ?? key),
          "aria-roledescription": state.labels.item,
          "aria-describedby": `${id}-instructions`,
          "aria-pressed": String(moving),
          "aria-disabled": state.disabledKeys.includes(key) ? "true" : undefined,
          tabindex: api.handles.tabIndex(state, { key, props: { value: key } }),
          "data-moving": moving ? "" : undefined,
        }
      },
      on: {
        keydown: (event, { el, api, key }) => {
          if (el) api.keydown(event, key, el, api.handles)
        },
        pointerdown: (event, { api, key }) => {
          if (event.button !== 0) return
          api.press(event, key)
          api.drag.pointerdown(event, key)
        },
      },
      bind: (el, part) => part.api.handles.bind(el, part),
    }),
    instructions: slot({
      attrs: (_state, { id }) => ({ id: `${id}-instructions`, hidden: "" }),
    }),
  }),
  agent: {
    actions: ["move", "reorder"],
    items: (api) => api.items(),
    shown: (state) => state.agentMoves,
  },
})

export { sortable }
export type { SortableAutoScroll, SortableOptions, SortableReason, SortableSelectReason }

import { reorderMessage, transferMessage, type ReorderMessage, type TransferMessage } from "@ui-sdk/core"

type SortableLabels = {
  /** The list's `aria-roledescription`. */
  list: string
  /** Each item's (or handle's) `aria-roledescription`. */
  item: string
  /** The drag handle's name, from the item's. */
  handle: (item: string) => string
  /** How to move an item with the keyboard; every item and handle is described by it. */
  instructions: string
  /** What screen readers hear as an item is picked up, moved, dropped or put back. */
  message: (message: ReorderMessage) => string
}

const sortableLabels: SortableLabels = {
  list: "sortable list",
  item: "sortable item",
  handle: (item) => `Reorder ${item}`,
  instructions: "Press Space to pick up. Use the arrow keys to move, Space to drop, Escape to cancel.",
  message: reorderMessage,
}

type TransferLabels = {
  /** Each card's (or handle's) `aria-roledescription`. */
  item: string
  handle: (item: string) => string
  instructions: string
  message: (message: TransferMessage) => string
}

const transferLabels: TransferLabels = {
  item: "draggable card",
  handle: (item) => `Move ${item}`,
  instructions:
    "Press Space to pick up. Use the arrow keys to move within a column, Left and Right to change columns, Space to drop, Escape to cancel.",
  message: transferMessage,
}

export { sortableLabels, transferLabels }
export type { SortableLabels, TransferLabels }

"use client"

import { createParts } from "@ui-sdk/react/primitive"
import { GripVerticalIcon } from "lucide-react"
import { createContext, use, useRef, type ComponentProps, type ReactNode, type RefObject } from "react"

import { sortableLabels, type SortableLabels } from "@/components/ui/sortable-labels"
import { sortable } from "@/components/ui/sortable-primitive"
import { useFlip } from "@/components/ui/use-flip"
import { cn, cnState } from "@/lib/utils"
import { assumeType } from "@/lib/narrow"

const Parts = createParts(sortable, { root: "div", entry: "div", handle: "button", instructions: "div" })

type SortableState = { order: string[]; moving: boolean }
type RootProps = ComponentProps<typeof Parts.Root>
/** `card`: separate bordered items; `row`: rows edge to edge in one bordered box; `plain`: no surface, for your own. */
type SortableVariant = "card" | "row" | "plain"

type SortableProps = Omit<RootProps, "children"> & {
  /** The items, or a function of the order to render them in (the draft's while an item moves). */
  children?: ReactNode | ((state: SortableState) => ReactNode)
  labels?: Partial<SortableLabels>
  variant?: SortableVariant
}

const VariantContext = createContext<SortableVariant>("card")

function Flip({
  root,
  order,
  children,
}: {
  root: RefObject<HTMLElement | null>
  order: string[]
  children: ReactNode
}) {
  useFlip(root, "[data-sortable-item]", order.join("\n"))
  return children
}

const orientationClassNames = {
  vertical: "flex flex-col gap-items",
  horizontal: "flex flex-row flex-wrap gap-items",
  grid: "grid grid-cols-[repeat(auto-fill,minmax(min(100%,10rem),1fr))] gap-items",
} as const

const rootVariantClassNames = {
  card: "",
  row: "gap-0 divide-y rounded-surface border bg-card text-card-foreground",
  plain: "",
} satisfies Record<SortableVariant, string>

function Sortable({
  className,
  children,
  labels,
  orientation = "vertical",
  variant = "card",
  ref,
  ...props
}: SortableProps) {
  const root = useRef<HTMLDivElement | null>(null)
  const text = { ...sortableLabels, ...labels }
  return (
    <Parts.Root
      orientation={orientation}
      labels={labels}
      ref={(node: HTMLDivElement | null) => {
        root.current = node
        if (typeof ref === "function") ref(node)
        else if (ref) ref.current = node
      }}
      className={cnState(
        cn(
          "group/sortable min-w-0 transition-none duration-panel ease-standard outline-none",
          orientationClassNames[orientation],
          rootVariantClassNames[variant],
        ),
        className,
      )}
      {...props}
    >
      {(state: SortableState) => (
        <VariantContext value={variant}>
          <Flip root={root} order={state.order}>
            {typeof children === "function" ? children(state) : children}
          </Flip>
          <Parts.Instructions>{text.instructions}</Parts.Instructions>
        </VariantContext>
      )}
    </Parts.Root>
  )
}

const itemVariantClassNames = {
  card: "flex items-center gap-inline rounded-lg border bg-card px-inset-item py-inset-item text-body text-card-foreground shadow-surface data-checked:border-primary",
  row: "flex items-center gap-inline bg-card px-inset-item py-inset-item text-body first:rounded-t-surface last:rounded-b-surface",
  plain: "rounded-control",
} satisfies Record<SortableVariant, string>

const itemClassName =
  "relative min-w-0 outline-none focus-visible:ring-2 focus-visible:ring-ring data-checked:bg-accent data-checked:text-accent-foreground data-disabled:opacity-60 data-moving:ring-2 data-moving:ring-ring data-grabbed:z-10 data-grabbed:translate-x-(--drag-x) data-grabbed:translate-y-(--drag-y) data-grabbed:shadow-floating group-data-preview/sortable:data-grabbed:translate-none group-data-preview/sortable:data-grabbed:opacity-40 group-data-preview/sortable:data-grabbed:shadow-none not-group-data-handle/sortable:cursor-grab not-group-data-handle/sortable:touch-none not-group-data-handle/sortable:select-none"

type SortableItemProps = ComponentProps<typeof Parts.Entry>

function SortableItem({ className, ...props }: SortableItemProps) {
  const variant = use(VariantContext)
  return <Parts.Entry className={cnState(cn(itemClassName, itemVariantClassNames[variant]), className)} {...props} />
}

type SortableHandleProps = Omit<ComponentProps<typeof Parts.Handle>, "value"> & {
  /** The item's name; the handle is called `labels.handle(label)`. */
  label?: string
  labels?: Partial<SortableLabels>
  value?: string
}

function SortableHandle({ className, label, labels, children, ...props }: SortableHandleProps) {
  const text = { ...sortableLabels, ...labels }
  return (
    <Parts.Handle
      aria-label={label === undefined ? undefined : text.handle(label)}
      className={cnState(
        "touch-target inline-flex size-control-sm shrink-0 cursor-grab touch-none items-center justify-center rounded-control text-muted-foreground outline-none select-none hover:bg-accent hover:text-accent-foreground focus-visible:ring-2 focus-visible:ring-ring aria-disabled:cursor-not-allowed aria-disabled:opacity-50 data-moving:bg-accent data-moving:text-accent-foreground [&_svg]:size-4",
        className,
      )}
      // Workaround: UI SDK fills `value` from the enclosing item (the slot's `from: "entry"`), but its part type still requires it.
      {...assumeType<ComponentProps<typeof Parts.Handle>>(props)}
    >
      {children ?? <GripVerticalIcon />}
    </Parts.Handle>
  )
}

export { Sortable, SortableHandle, SortableItem }
export type { SortableHandleProps, SortableItemProps, SortableProps, SortableState, SortableVariant }

"use client"

import { useLayoutEffect, useRef, type RefObject } from "react"

type Point = { x: number; y: number }

function firstOf(list: string) {
  let depth = 0
  for (let index = 0; index < list.length; index++) {
    const char = list[index]
    if (char === "(") depth++
    else if (char === ")") depth--
    else if (char === "," && depth === 0) return list.slice(0, index).trim()
  }
  return list.trim()
}

function milliseconds(value: string) {
  const first = firstOf(value)
  const number = Number.parseFloat(first)
  if (Number.isNaN(number)) return 0
  return first.endsWith("ms") ? number : number * 1000
}

function where(el: HTMLElement, origin: DOMRect): Point {
  const rect = el.getBoundingClientRect()
  return { x: rect.left - origin.left, y: rect.top - origin.top }
}

/**
 * Slides the elements matching `selector` inside `root` from where they were to where they are whenever `trigger`
 * changes, so neighbours make room instead of jumping. Timing comes from the root's own `transition-duration` and
 * `transition-timing-function` (the motion tokens), and nothing moves under reduced motion. An element carrying
 * `data-grabbed` follows the pointer and is left alone.
 */
function useFlip(root: RefObject<HTMLElement | null>, selector: string, trigger: unknown) {
  const last = useRef(new Map<Element, Point>())
  useLayoutEffect(() => {
    const container = root.current
    if (!container) return
    const elements = [...container.querySelectorAll<HTMLElement>(selector)]
    const origin = container.getBoundingClientRect()
    const next = new Map<Element, Point>(elements.map((el) => [el, where(el, origin)]))
    const previous = last.current
    last.current = next
    if (typeof matchMedia === "function" && matchMedia("(prefers-reduced-motion: reduce)").matches) return
    const style = getComputedStyle(container)
    const duration = milliseconds(style.transitionDuration)
    if (duration < 1) return
    const easing = firstOf(style.transitionTimingFunction) || "ease"
    for (const el of elements) {
      const was = previous.get(el)
      const now = next.get(el)
      if (!was || !now || el.hasAttribute("data-grabbed") || typeof el.animate !== "function") continue
      const dx = was.x - now.x
      const dy = was.y - now.y
      if (Math.abs(dx) < 1 && Math.abs(dy) < 1) continue
      el.animate([{ translate: `${String(dx)}px ${String(dy)}px` }, { translate: "0 0" }], {
        duration,
        easing,
        composite: "add",
      })
    }
    // oxlint-disable-next-line react/exhaustive-effect-dependencies -- `trigger` is the order: the effect runs only when it changes
  }, [root, selector, trigger])
}

export { useFlip }
